<?php require '../config/db.php';require '../config/auth.php';require_role('admin','login.php');$u=current_user();$counts=[];foreach(['users'=>"SELECT COUNT(*) FROM users WHERE role='parishioner'",'pending'=>"SELECT COUNT(*) FROM appointments WHERE status='pending'",'today'=>"SELECT COUNT(*) FROM appointments WHERE appointment_date=CURDATE() AND status<>'cancelled'",'services'=>"SELECT COUNT(*) FROM services WHERE status='active'"] as $k=>$q)$counts[$k]=(int)$pdo->query($q)->fetchColumn();$recent=$pdo->query("SELECT a.*,s.name service_name,u.full_name person FROM appointments a JOIN services s ON s.id=a.service_id JOIN users u ON u.id=a.user_id ORDER BY a.created_at DESC LIMIT 7")->fetchAll();?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Dashboard</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><div class="shell"><?php include 'includes/sidebar.php'?><main class="main"><header class="topbar"><div><button class="btn light mobile-toggle" data-nav-toggle>☰</button><div class="eyebrow">Administration</div><h1>Parish overview.</h1></div><div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap"><a class="btn light" href="admins.php">+ Add administrator</a><div class="user-chip"><?=e($u['full_name'])?> · Administrator</div></div></header><section class="grid stats"><div class="card stat"><span class="muted">Parishioners</span><strong><?=$counts['users']?></strong></div><div class="card stat"><span class="muted">Pending requests</span><strong><?=$counts['pending']?></strong></div><div class="card stat"><span class="muted">Appointments today</span><strong><?=$counts['today']?></strong></div><div class="card stat"><span class="muted">Active services</span><strong><?=$counts['services']?></strong></div></section><br><section class="card table-wrap"><h2>Recent requests</h2><table class="table"><thead><tr><th>Reference</th><th>Parishioner</th><th>Service</th><th>Date</th><th>Status</th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><?=e($r['reference_no'])?></td><td><?=e($r['person'])?></td><td><?=e($r['service_name'])?></td><td><?=date('M j, Y',strtotime($r['appointment_date']))?></td><td><span class="badge <?=e($r['status'])?>"><?=e($r['status'])?></span></td></tr><?php endforeach?></tbody></table></section></main></div><script src="../assets/js/script.js"></script></body></html>
